using System.Text.RegularExpressions;

namespace HiveOps.Application.Support;

/// <summary>
/// Extracts structural pieces (target table, WHERE clause) from SQL statements
/// generated by the support auto-workflow. Shared by the incident worker and the
/// backup service so table/row detection stays consistent across the pipeline.
/// </summary>
public static class SqlStatementParser
{
    // Each pattern captures the table name and, optionally, the schema prefix.
    // Bare, [bracketed] and "double-quoted" identifiers are supported.
    private const string Ident = @"(?:\[\w+\]|""[^""\r\n]+""|\w+)";
    private const string IdentDot = @"(?:(?:\[\w+\]|""[^""\r\n]+""|\w+)\.)";

    private static readonly Regex UpdateTablePattern = new(
        $@"\bUPDATE\s+(?<schema>{IdentDot})?(?<table>{Ident})\s+SET\b",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    private static readonly Regex InsertTablePattern = new(
        $@"\bINSERT\s+INTO\s+(?<schema>{IdentDot})?(?<table>{Ident})",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    private static readonly Regex DeleteTablePattern = new(
        $@"\bDELETE\s+FROM\s+(?<schema>{IdentDot})?(?<table>{Ident})",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    private static readonly Regex FromTablePattern = new(
        $@"\bFROM\s+(?<schema>{IdentDot})?(?<table>{Ident})",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    private static readonly Regex WhereKeywordPattern = new(
        @"\bWHERE\b",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    // Matches "FROM <schema>.<table> [AS] <alias>" — used to resolve UPDATE
    // statements written against an alias: UPDATE p SET ... FROM products p.
    private static readonly Regex FromAliasPattern = new(
        $@"\bFROM\s+(?<schema>{IdentDot})?(?<table>{Ident})\s+(?:AS\s+)?(?<alias>\w+)\b",
        RegexOptions.IgnoreCase | RegexOptions.Compiled);

    /// <summary>
    /// Returns the first table targeted by the statement, qualified with schema
    /// when present (e.g. "public.orders"). Supports UPDATE/INSERT/DELETE/SELECT
    /// and returns null when no table can be identified.
    /// </summary>
    public static string? ExtractTableName(string sql)
    {
        if (string.IsNullOrWhiteSpace(sql))
            return null;

        var updateMatch = UpdateTablePattern.Match(sql);
        if (updateMatch.Success)
        {
            var table = Unquote(updateMatch.Groups["table"].Value);
            var schema = updateMatch.Groups["schema"].Success
                ? Unquote(updateMatch.Groups["schema"].Value.TrimEnd('.'))
                : null;

            // UPDATE <alias> SET ... FROM <schema>.<realTable> <alias>: resolve
            // the alias to the real table so existence checks and backups use it.
            foreach (Match from in FromAliasPattern.Matches(sql))
            {
                var alias = from.Groups["alias"].Value;
                if (!string.Equals(alias, table, StringComparison.OrdinalIgnoreCase))
                    continue;

                var fromTable = Unquote(from.Groups["table"].Value);
                var fromSchema = from.Groups["schema"].Success
                    ? Unquote(from.Groups["schema"].Value.TrimEnd('.'))
                    : null;
                return string.IsNullOrEmpty(fromSchema) ? fromTable : $"{fromSchema}.{fromTable}";
            }

            return string.IsNullOrEmpty(schema) ? table : $"{schema}.{table}";
        }

        foreach (var pattern in new[] { InsertTablePattern, DeleteTablePattern, FromTablePattern })
        {
            var match = pattern.Match(sql);
            if (!match.Success)
                continue;

            var table = Unquote(match.Groups["table"].Value);
            var schema = match.Groups["schema"].Success
                ? Unquote(match.Groups["schema"].Value.TrimEnd('.'))
                : null;

            return string.IsNullOrEmpty(schema) ? table : $"{schema}.{table}";
        }

        return null;
    }

    /// <summary>
    /// Returns the WHERE clause (starting at the WHERE keyword) of the first
    /// statement that has one, truncated at the statement-terminating ';'.
    /// Returns null when the SQL has no WHERE clause.
    /// </summary>
    public static string? ExtractWhereClause(string sql)
    {
        if (string.IsNullOrWhiteSpace(sql))
            return null;

        var match = WhereKeywordPattern.Match(sql);
        if (!match.Success)
            return null;

        var fromWhere = sql[match.Index..];
        var semicolon = IndexOfStatementTerminator(fromWhere);
        var clause = semicolon >= 0 ? fromWhere[..semicolon] : fromWhere;

        clause = clause.Trim().TrimEnd(';').TrimEnd();
        return clause.Length == 0 ? null : clause;
    }

    /// <summary>
    /// Splits a script on ';' separators and returns the non-empty statements
    /// (without the separator). Semicolons inside single-quoted string literals
    /// (including the T-SQL '' escape) do not split. Comments attached to a
    /// statement are kept.
    /// </summary>
    public static IReadOnlyList<string> SplitStatements(string sql)
    {
        if (string.IsNullOrWhiteSpace(sql))
            return Array.Empty<string>();

        var statements = new List<string>();
        var start = 0;
        var inLiteral = false;

        for (var i = 0; i < sql.Length; i++)
        {
            var c = sql[i];
            if (c == '\'')
            {
                if (inLiteral && i + 1 < sql.Length && sql[i + 1] == '\'')
                {
                    i++;
                    continue;
                }
                inLiteral = !inLiteral;
                continue;
            }
            if (c == ';' && !inLiteral)
            {
                AddStatement(statements, sql[start..i]);
                start = i + 1;
            }
        }

        AddStatement(statements, sql[start..]);
        return statements;
    }

    /// <summary>Removes [bracket] and "double-quote" wrappers from an identifier part.</summary>
    private static string Unquote(string identifier) =>
        identifier.Trim().Trim('[', ']', '"');

    private static void AddStatement(List<string> statements, string statement)
    {
        var trimmed = statement.Trim();
        if (trimmed.Length > 0)
            statements.Add(trimmed);
    }

    /// <summary>
    /// Returns the index of the first ';' outside of a single-quoted literal,
    /// or -1 when the statement is unterminated.
    /// </summary>
    private static int IndexOfStatementTerminator(string sql)
    {
        var inLiteral = false;
        for (var i = 0; i < sql.Length; i++)
        {
            var c = sql[i];
            if (c == '\'')
            {
                if (inLiteral && i + 1 < sql.Length && sql[i + 1] == '\'')
                {
                    i++;
                    continue;
                }
                inLiteral = !inLiteral;
                continue;
            }
            if (c == ';' && !inLiteral)
                return i;
        }
        return -1;
    }
}
